import{_ as s,o as t,c as a,a0 as n}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"Module guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/module.md","filePath":"guide/module.md"}'),o={name:"guide/module.md"};function i(l,e,d,r,p,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="module-guide" tabindex="-1">Module guide <a class="header-anchor" href="#module-guide" aria-label="Permalink to &quot;Module guide&quot;">​</a></h1><p>KernelSU provides a module mechanism that achieves the effect of modifying the system directory while maintaining the integrity of the system partition. This mechanism is commonly known as &quot;systemless&quot;.</p><p>The module mechanism of KernelSU is almost the same as that of Magisk. If you&#39;re familiar with Magisk module development, developing KernelSU modules is very similar. You can skip the introduction of modules below and just read <a href="./difference-with-magisk.html">Difference with Magisk</a>.</p><div class="warning custom-block"><p class="custom-block-title">METAMODULE ONLY NEEDED FOR SYSTEM FILE MODIFICATION</p><p>KernelSU uses a <a href="./metamodule.html">metamodule</a> architecture for mounting the <code>system</code> directory. <strong>Only if your module needs to modify <code>/system</code> files</strong> (via the <code>system</code> directory) do you need to install a metamodule (such as <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>). Other module features like scripts, sepolicy rules, and system.prop work without a metamodule.</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>KernelSU&#39;s modules support displaying interfaces and interacting with users. For more details, refer to the <a href="./module-webui.html">WebUI documentation</a>.</p><h2 id="module-configuration" tabindex="-1">Module Configuration <a class="header-anchor" href="#module-configuration" aria-label="Permalink to &quot;Module Configuration&quot;">​</a></h2><p>KernelSU provides a built-in configuration system that allows modules to store persistent or temporary key-value settings. For more details, refer to the <a href="./module-config.html">Module Configuration documentation</a>.</p><h2 id="one-shot-scripts" tabindex="-1">One-shot Scripts <a class="header-anchor" href="#one-shot-scripts" aria-label="Permalink to &quot;One-shot Scripts&quot;">​</a></h2><p>A module ZIP can also be a one-shot script that the KernelSU manager runs once instead of installing. For more details, refer to the <a href="./module-script.html">One-shot Scripts documentation</a>.</p><h2 id="busybox" tabindex="-1">BusyBox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;BusyBox&quot;">​</a></h2><p>KernelSU ships with a feature-complete BusyBox binary (including full SELinux support). The executable is located at <code>/data/adb/ksu/bin/busybox</code>. KernelSU&#39;s BusyBox supports runtime toggle-able &quot;ASH Standalone Shell Mode&quot;. What this Standalone Mode means is that when running in the <code>ash</code> shell of BusyBox, every single command will directly use the applet within BusyBox, regardless of what is set as <code>PATH</code>. For example, commands like <code>ls</code>, <code>rm</code>, <code>chmod</code> will <strong>NOT</strong> use what is in <code>PATH</code> (in the case of Android by default it will be <code>/system/bin/ls</code>, <code>/system/bin/rm</code>, and <code>/system/bin/chmod</code> respectively), but will instead directly call internal BusyBox applets. This makes sure that scripts always run in a predictable environment and always have the full suite of commands no matter which Android version it is running on. To force a command <em>not</em> to use BusyBox, you have to call the executable with full paths.</p><p>Every single shell script running in the context of KernelSU will be executed in BusyBox&#39;s <code>ash</code> shell with Standalone Mode enabled. For what is relevant to 3rd party developers, this includes all boot scripts and module installation scripts.</p><p>For those who want to use this Standalone Mode feature outside of KernelSU, there are 2 ways to enable it:</p><ol><li>Set environment variable <code>ASH_STANDALONE</code> to <code>1</code> <br>Example: <code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>Toggle with command-line options:<br><code>/data/adb/ksu/bin/busybox sh -o standalone &lt;script&gt;</code></li></ol><p>To make sure all subsequent <code>sh</code> shell executed also runs in Standalone Mode, option 1 is the preferred method (and this is what KernelSU and the KernelSU manager use internally) as environment variables are inherited down to child processes.</p><div class="tip custom-block"><p class="custom-block-title">DIFFERENCE WITH MAGISK</p><p>KernelSU&#39;s BusyBox is now using the binary file compiled directly from the Magisk project. <strong>Thanks to Magisk!</strong> Therefore, you don&#39;t need to worry about compatibility issues between BusyBox scripts in Magisk and KernelSU, as they&#39;re exactly the same!</p></div><h2 id="kernelsu-modules" tabindex="-1">KernelSU modules <a class="header-anchor" href="#kernelsu-modules" aria-label="Permalink to &quot;KernelSU modules&quot;">​</a></h2><p>A KernelSU module is a folder placed in <code>/data/adb/modules</code> with the structure below:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- The folder is named with the ID of the module</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Module Identity ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- This file stores the metadata of the module</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Main Contents ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- This folder will be mounted if skip_mount does not exist</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Status Flags ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- If exists, KernelSU will NOT mount your system folder</span></span>
<span class="line"><span>│   ├── disable             &lt;--- If exists, the module will be disabled</span></span>
<span class="line"><span>│   ├── remove              &lt;--- If exists, the module will be removed next reboot</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Optional Files ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- This script will be executed in post-fs-data</span></span>
<span class="line"><span>│   ├── post-mount.sh       &lt;--- This script will be executed in post-mount</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- This script will be executed in late_start service</span></span>
<span class="line"><span>│   ├── boot-completed.sh   &lt;--- This script will be executed on boot completed</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- This script will be executed when KernelSU removes your module</span></span>
<span class="line"><span>|   ├── action.sh           &lt;--- This script will be executed when user click the Action button in KernelSU app</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- Properties in this file will be loaded as system properties by resetprop</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- Additional custom sepolicy rules</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- .rc files in this directory will be injected into init.rc on boot</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   ├── preinit/            &lt;--- preinit.conf and its files, run before SELinux policy is loaded</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Auto Generated, DO NOT MANUALLY CREATE OR MODIFY ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- A symlink to $MODID/system/vendor</span></span>
<span class="line"><span>│   ├── product             &lt;--- A symlink to $MODID/system/product</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- A symlink to $MODID/system/system_ext</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Any additional files / folders are allowed ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">DIFFERENCE WITH MAGISK</p><p>KernelSU doesn&#39;t have built-in support for Zygisk, so there is no content related to Zygisk in the module. However, you can use <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> to support Zygisk modules. In this case, the content of the Zygisk module is identical to that supported by Magisk.</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p><code>module.prop</code> is a configuration file for a module. In KernelSU, if a module doesn&#39;t contain this file, it won&#39;t be recognized as a module. The format of this file is as follows:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (optional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (optional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (optional)</span></span></code></pre></div><ul><li><code>id</code> has to match this regular expression: <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code><br> Example: ✓ <code>a_module</code>, ✓ <code>a.module</code>, ✓ <code>module-101</code>, ✗ <code>a module</code>, ✗ <code>1_module</code>, ✗ <code>-a-module</code><br> This is the <strong>unique identifier</strong> of your module. You should not change it once published.</li><li><code>versionCode</code> has to be an <strong>integer</strong>. This is used to compare versions.</li><li>Others that were not mentioned above can be any <strong>single line</strong> string.</li><li>Make sure to use the <code>UNIX (LF)</code> line break type and not the <code>Windows (CR+LF)</code> or <code>Macintosh (CR)</code>.</li><li><code>actionIcon</code> and <code>webuiIcon</code> are optional icon paths used as the default icons for the module action shortcut and WebUI shortcut in the Manager. These paths must be relative to the module root directory. For example, <code>actionIcon=icon/icon.png</code> will be resolved as <code>&lt;MODDIR&gt;/icon/icon.png</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">DYNAMIC DESCRIPTION</p><p>The <code>description</code> field can be dynamically overridden at runtime using the module configuration system. See <a href="./module-config.html#overriding-module-description">Overriding Module Description</a> for details.</p></div><h3 id="shell-scripts" tabindex="-1">Shell scripts <a class="header-anchor" href="#shell-scripts" aria-label="Permalink to &quot;Shell scripts&quot;">​</a></h3><p>Please read the <a href="#boot-scripts">Boot scripts</a> section to understand the difference between <code>post-fs-data.sh</code> and <code>service.sh</code>. For most module developers, <code>service.sh</code> should be good enough if you just need to run a boot script, if you need to run the script after boot completed, please use <code>boot-completed.sh</code>. If you want to do something after mounting OverlayFS, please use <code>post-mount.sh</code>.</p><p>In all scripts of your module, please use <code>MODDIR=\${0%/*}</code> to get your module&#39;s base directory path; do <strong>NOT</strong> hardcode your module path in scripts.</p><div class="tip custom-block"><p class="custom-block-title">DIFFERENCE WITH MAGISK</p><p>You can use the environment variable <code>KSU</code> to determine if a script is running in KernelSU or Magisk. If running in KernelSU, this value will be set to <code>true</code>.</p></div><h3 id="system-directory" tabindex="-1"><code>system</code> directory <a class="header-anchor" href="#system-directory" aria-label="Permalink to &quot;\`system\` directory&quot;">​</a></h3><p>The contents of this directory will be overlaid on top of the system&#39;s <code>/system</code> partition after the system is booted. This means that:</p><div class="tip custom-block"><p class="custom-block-title">METAMODULE REQUIREMENT</p><p>The <code>system</code> directory is only mounted if you have a metamodule installed that provides mounting functionality (such as <code>meta-overlayfs</code>). The metamodule handles how modules are mounted. See the <a href="./metamodule.html">Metamodule Guide</a> for more information.</p></div><ol><li>Files with the same name as those in the corresponding directory in the system will be overwritten by the files in this directory.</li><li>Folders with the same name as those in the corresponding directory in the system will be merged with the folders in this directory.</li></ol><p>If you want to delete a file or folder in the original system directory, you need to create a file with the same name as the file/folder in the module directory using <code>mknod filename c 0 0</code>. This way, the OverlayFS system will automatically &quot;whiteout&quot; this file as if it has been deleted (the /system partition isn&#39;t actually changed).</p><p>You can also declare a variable named <code>REMOVE</code> containing a list of directories in <code>customize.sh</code> to execute removal operations, and KernelSU will automatically execute <code>mknod &lt;TARGET&gt; c 0 0</code> in the corresponding directories of the module. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>The above list will execute <code>mknod $MODPATH/system/app/YouTube c 0 0</code> and <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>, <code>/system/app/YouTube</code> and <code>/system/app/Bloatware</code> will be removed after the module takes effect.</p><p>If you want to replace a directory in the system, you need to create a directory with the same path in your module directory, and then set the attribute <code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code> for this directory. This way, the OverlayFS system will automatically replace the corresponding directory in the system (without changing the /system partition).</p><p>You can declare a variable named <code>REPLACE</code> in your <code>customize.sh</code> file, which includes a list of directories to be replaced, and KernelSU will automatically perform the corresponding operations in your module directory. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REPLACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>This list will automatically create the directories <code>$MODPATH/system/app/YouTube</code> and <code>$MODPATH/system/app/Bloatware</code>, and then execute <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/YouTube</code> and <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/Bloatware</code>. After the module takes effect, <code>/system/app/YouTube</code> and <code>/system/app/Bloatware</code> will be replaced with empty directories.</p><div class="tip custom-block"><p class="custom-block-title">DIFFERENCE WITH MAGISK</p><p>KernelSU uses a <a href="./metamodule.html">metamodule architecture</a> where mounting is delegated to pluggable metamodules. The official <code>meta-overlayfs</code> metamodule uses the kernel&#39;s OverlayFS for systemless modifications, while Magisk uses magic mount (bind mount) built directly into its core. Both achieve the same goal: modifying <code>/system</code> files without physically modifying the <code>/system</code> partition. KernelSU&#39;s approach provides more flexibility and reduces detection surface.</p></div><p>If you&#39;re interested in OverlayFS, it&#39;s recommended to read the Linux Kernel&#39;s <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">documentation on OverlayFS</a>. For details on KernelSU&#39;s metamodule system, see the <a href="./metamodule.html">Metamodule Guide</a>.</p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>This file follows the same format as <code>build.prop</code>. Each line comprises of <code>[key]=[value]</code>.</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>If your module requires some additional sepolicy patches, please add those rules into this file. Each line in this file will be treated as a policy statement.</p><h3 id="initrc-injection" tabindex="-1">initrc Injection <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;initrc Injection {#initrc-injection}&quot;">​</a></h3><p>KernelSU provides a mechanism to inject custom Android Init RC directives into the system&#39;s <code>init.rc</code>. This allows modules to register custom Android services, set property triggers, or perform other Init language actions without modifying the system partition.</p><p>During boot, the KernelSU kernel module intercepts <code>read()</code> and <code>fstat()</code> system calls. When the Android init process reads <code>/system/etc/init/hw/init.rc</code>, KernelSU transparently appends the custom RC content to the end of the file. The init process parses these injected directives just like the original init.rc content.</p><p>On the userspace side, ksud concatenates all <code>.rc</code> files from enabled modules into a single <code>modules.rc</code> file, stored on the <code>/metadata</code> partition. This file is automatically regenerated whenever a module&#39;s state changes (install, enable, disable, uninstall, etc.).</p><h4 id="module-initrc-files" tabindex="-1">Module initrc Files <a class="header-anchor" href="#module-initrc-files" aria-label="Permalink to &quot;Module initrc Files&quot;">​</a></h4><p>Create an <code>initrc/</code> subdirectory in your module directory and place your <code>.rc</code> files there:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Files must have an <code>.rc</code> extension.</li><li>As long as the module is enabled, all <code>.rc</code> files in the <code>initrc/</code> directory will be included (executable permission is not required).</li><li>Files are processed in <strong>alphabetical order of file name</strong> within the directory, and modules are processed in <strong>alphabetical order of module ID</strong>.</li></ul></div><h4 id="general-initrc-files" tabindex="-1">General initrc Files <a class="header-anchor" href="#general-initrc-files" aria-label="Permalink to &quot;General initrc Files&quot;">​</a></h4><p>In addition to module-level RC files, you can place <code>.rc</code> files in the global directory:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">General initrc files require executable permission</p><p>Unlike the module <code>initrc/</code> directory, files in <code>/data/adb/initrc.d/</code> <strong>must have executable permissions</strong> to be included. Non-executable <code>.rc</code> files will be silently skipped.</p></div><p>General <code>initrc.d/</code> files are processed before any module RC files.</p><h4 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h4><p>Here is an example <code>.rc</code> file that registers a custom Android service:</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>If this file is placed at <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>, it will register a service named <code>myservice</code> at boot and start it when <code>sys.boot_completed=1</code> is reached.</p><h4 id="manual-refresh" tabindex="-1">Manual Refresh <a class="header-anchor" href="#manual-refresh" aria-label="Permalink to &quot;Manual Refresh&quot;">​</a></h4><p>You can manually trigger the regeneration of <code>modules.rc</code> with the following command (changes take effect on the next boot):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>initrc injection happens extremely early in the boot process (when init reads init.rc), <strong>before</strong> post-fs-data and any module scripts are executed.</li><li>The injected RC content is treated by init as part of the original init.rc, supporting all Android Init language syntax (service definitions, triggers, property settings, etc.).</li><li>initrc injection is <strong>not available</strong> in <strong>late-load mode</strong>, as the system call hooks are not installed in that mode.</li><li>Module RC injection can be disabled by passing the <code>--no-custom-rc</code> parameter when patching the image with ksud.</li></ul></div><h3 id="preinit" tabindex="-1">preinit <a class="header-anchor" href="#preinit" aria-label="Permalink to &quot;preinit {#preinit}&quot;">​</a></h3><p>A module can run a few actions <strong>before the SELinux policy is loaded and before init.rc is parsed</strong>, for example to load a kernel module, run a static program or write procfs/sysfs. Put them in a <code>preinit/</code> directory described by <code>preinit/preinit.conf</code>:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── preinit/</span></span>
<span class="line"><span>│   ├── preinit.conf</span></span>
<span class="line"><span>│   ├── kmod/foo.ko</span></span>
<span class="line"><span>│   └── bin/fixup</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>ksud copies the whole <code>preinit/</code> directory of every enabled module to the <code>/metadata</code> partition. On the next boot a runner embedded in the KernelSU kernel module executes the actions when first stage init hands over to <code>/system/bin/init selinux_setup</code>. At this point <code>/metadata</code>, <code>/system</code> and <code>/vendor</code> are mounted and <code>/proc</code>, <code>/sys</code> and <code>/dev</code> are available, but there is no policy, no property service and no ueventd yet. Modules are processed in alphabetical order of module ID.</p><h4 id="preinit-conf" tabindex="-1">preinit.conf <a class="header-anchor" href="#preinit-conf" aria-label="Permalink to &quot;preinit.conf&quot;">​</a></h4><p>One action per line. Lines starting with <code>#</code> and empty lines are ignored. Arguments are separated by blanks; use double quotes to keep blanks in an argument and <code>\\&quot;</code> / <code>\\\\</code> for a literal quote or backslash. Variables are <strong>not</strong> expanded. Relative paths are relative to the module&#39;s preinit directory. Lines are at most 4 KB and the file at most 64 KB.</p><table tabindex="0"><thead><tr><th>Action</th><th>Syntax</th><th>Meaning</th></tr></thead><tbody><tr><td><code>insmod</code></td><td><code>insmod &lt;ko&gt; [params...]</code></td><td>Load a kernel module. Undefined symbols are looked up in the kernel&#39;s kallsyms and bound before <code>init_module</code>, so the module may use non-exported symbols; a module that needs no such binding is loaded with <code>finit_module</code>. Parameters are joined with spaces</td></tr><tr><td><code>exec</code></td><td><code>exec [-t &lt;ms&gt;] &lt;prog&gt; [args...]</code></td><td>Run a program and wait for it. A non-zero exit status is a failure. It is killed after 5000 ms by default</td></tr><tr><td><code>write</code></td><td><code>write &lt;path&gt; &lt;content&gt;</code></td><td>Write <code>content</code> to an existing file, without a trailing newline. Meant for procfs/sysfs</td></tr></tbody></table><p>Append <code>?</code> to an action to ignore its failure. Any other failing action stops the rest of <strong>this</strong> module; the next module still runs.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># preinit/preinit.conf</span></span>
<span class="line"><span>insmod   kmod/foo.ko  debug=1 name=&quot;a b&quot;</span></span>
<span class="line"><span>insmod?  kmod/optional.ko</span></span>
<span class="line"><span>exec -t 10000  bin/fixup --flag</span></span>
<span class="line"><span>write    /proc/sys/kernel/printk_devkmsg on</span></span></code></pre></div><p>Programs started by <code>exec</code> run as root with full capabilities and no SELinux restriction. Their working directory is the module&#39;s preinit directory, stdin is <code>/dev/null</code> and stdout/stderr are forwarded to the kernel log line by line with a <code>ksu_preinit[&lt;MODID&gt;]:</code> prefix. The environment contains only <code>KSU=true</code>, <code>KSU_PREINIT=1</code>, <code>MODID</code>, <code>PREINIT_DIR</code> and <code>PATH=/system/bin:/vendor/bin</code>.</p><div class="warning custom-block"><p class="custom-block-title">LIMITATIONS</p><ul><li>There is no shell: only <strong>statically linked</strong> programs work, <code>/apex</code> is not mounted yet.</li><li><code>/dev</code> only contains the nodes created by first stage init; ueventd is not running.</li><li>The firmware loader has no userspace fallback, firmware must be loadable directly from <code>/vendor/firmware</code> and similar paths.</li><li>Properties can neither be read nor set.</li><li>Only the vendor modules of first stage are loaded. A <code>.ko</code> that depends on symbols from vendor_dlkm (loaded in second stage) fails to load.</li><li>Nothing may keep running: all processes left over when preinit ends are killed. The whole preinit stage is limited to 30 seconds.</li><li>Changes take effect on the <strong>next boot</strong>; a hot install does not run preinit.</li><li>The directory and <code>preinit.conf</code> (and the <code>.ko</code> / program files used) must be owned by root and not writable by group or others. ksud takes care of this when copying.</li><li>ksud keeps the permission bits of each file (minus group/other write). The installer sets module files to <code>0644</code>, so programs run by <code>exec</code> need <code>set_perm $MODPATH/preinit/bin/xxx 0 0 0755</code> in <code>customize.sh</code>.</li></ul></div><h4 id="space-on-metadata" tabindex="-1">Space on /metadata <a class="header-anchor" href="#space-on-metadata" aria-label="Permalink to &quot;Space on /metadata&quot;">​</a></h4><p><code>/metadata</code> is small (often around 10 MB) and also holds encryption keys and OTA state. ksud therefore keeps at least 8 MB free and uses at most 4 MB for preinit. Modules are copied in alphabetical order of module ID; a module that does not fit is skipped entirely, and the installer prints a warning. Check the result with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preinit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><h4 id="bootloop-protection" tabindex="-1">Bootloop protection <a class="header-anchor" href="#bootloop-protection" aria-label="Permalink to &quot;Bootloop protection&quot;">​</a></h4><p>Before running any action the runner increments a boot counter, which ksud clears when boot completes. After 3 boots in a row that did not complete, preinit is skipped and stays disabled until the preinit content of a module changes or you run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preinit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span></span></code></pre></div><p>preinit is also not run in charger mode, and safe mode disables all modules, which removes their preinit content for the next boot. To get out of a bootloop by hand, delete <code>/metadata/vold/ksu/preinit</code> (or <code>/metadata/watchdog/ksu/preinit</code>, <code>/metadata/ksu/preinit</code>, whichever exists) from recovery, or <code>fastboot boot</code> the stock image and delete it there.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>preinit is <strong>not available</strong> in <strong>late-load mode</strong> and on devices that do not use a two stage init (devices launched with system-as-root before Android 10).</li><li>When the running kernel does not run preinit (late-load mode, <code>preinit=0</code>, or a kernel built without it), ksud copies nothing to <code>/metadata</code> and <code>ksud module preinit status</code> reports the modules as <code>unsupported</code>.</li><li>preinit can be disabled entirely with the <code>preinit=0</code> parameter of the KernelSU kernel module, which <code>ksud boot-patch</code> / <code>boot-patch-v2</code> set with <code>--no-preinit</code>.</li><li>Anyone who can write to <code>/metadata</code> can run code this early. Only install modules you trust.</li></ul></div><h2 id="module-installer" tabindex="-1">Module installer <a class="header-anchor" href="#module-installer" aria-label="Permalink to &quot;Module installer&quot;">​</a></h2><p>A KernelSU module installer is a KernelSU module packaged in a ZIP file that can be flashed in the KernelSU manager. The simplest KernelSU module installer is just a KernelSU module packed as a ZIP file.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Optional, more details later)</span></span>
<span class="line"><span>│                                           This script will be sourced by update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* The rest of module&#39;s files */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>KernelSU module is <strong>NOT</strong> compatible for installation in a custom Recovery!</p></div><h3 id="customization" tabindex="-1">Customization <a class="header-anchor" href="#customization" aria-label="Permalink to &quot;Customization&quot;">​</a></h3><p>If you need to customize the module installation process, optionally you can create a script in the installer named <code>customize.sh</code>. This script will be <strong>sourced</strong> (not executed) by the module installer script after all files are extracted and default permissions and secontext are applied. This is very useful if your module requires additional setup based on the device ABI, or you need to set special permissions/secontext for some of your module files.</p><p>If you would like to fully control and customize the installation process, declare <code>SKIPUNZIP=1</code> in <code>customize.sh</code> to skip all default installation steps. By doing so, your <code>customize.sh</code> will be responsible to install everything by itself.</p><p>The <code>customize.sh</code> script runs in KernelSU&#39;s BusyBox <code>ash</code> shell with Standalone Mode enabled. The following variables and functions are available:</p><h4 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h4><ul><li><code>KSU</code> (bool): a variable to mark that the script is running in the KernelSU environment, and the value of this variable will always be true. You can use it to distinguish between KernelSU and Magisk.</li><li><code>KSU_VER</code> (string): the version string of currently installed KernelSU (e.g. <code>v0.4.0</code>).</li><li><code>KSU_VER_CODE</code> (int): the version code of currently installed KernelSU in userspace (e.g. <code>10672</code>).</li><li><code>KSU_KERNEL_VER_CODE</code> (int): the version code of currently installed KernelSU in kernel space (e.g. <code>10672</code>).</li><li><code>BOOTMODE</code> (bool): always be <code>true</code> in KernelSU.</li><li><code>MODPATH</code> (path): the path where your module files should be installed.</li><li><code>TMPDIR</code> (path): a place where you can temporarily store files.</li><li><code>ZIPFILE</code> (path): your module&#39;s installation ZIP.</li><li><code>ARCH</code> (string): the CPU architecture of the device. Value is either <code>arm</code>, <code>arm64</code>, <code>x86</code>, or <code>x64</code>.</li><li><code>IS64BIT</code> (bool): <code>true</code> if <code>$ARCH</code> is either <code>arm64</code> or <code>x64</code>.</li><li><code>API</code> (int): the API level (Android version) of the device (e.g., <code>23</code> for Android 6.0).</li><li><code>KSU_UAPI_VER</code> (int): the UAPI version of KernelSU userspace (ksud) (e.g., <code>2</code>). This version is incremented when there are breaking changes in the kernel driver, and can be used by modules to check compatibility.</li><li><code>KSU_RUNTIME_MODE</code> (string): the current KernelSU runtime mode. Possible values are <code>built-in</code> (a.k.a. GKI mode, compiled into the kernel), <code>lkm</code> (loaded as a kernel module at boot), or <code>late-load</code> (loaded as a kernel module after boot).</li><li><code>KSU_LATE_LOAD</code> (int?): if KernelSU is late-loaded after boot, this variable is set to <code>1</code>; otherwise it is not set.</li><li><code>KSU_HAS_HOT_INSTALL</code> (bool): <code>true</code> if the installer supports <a href="#hot-install">hot install</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>In KernelSU, <code>MAGISK_VER_CODE</code> is always <code>25200</code>, and <code>MAGISK_VER</code> is always <code>v25.2</code>. Please don&#39;t use these two variables to determine whether KernelSU is running or not.</p></div><h4 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    print &lt;msg&gt; to console</span></span>
<span class="line"><span>    Avoid using &#39;echo&#39; as it will not display in custom recovery&#39;s console</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    print error message &lt;msg&gt; to console and terminate the installation</span></span>
<span class="line"><span>    Avoid using &#39;exit&#39; as it will skip the termination cleanup steps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    this function is a shorthand for the following commands:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    for all files in &lt;directory&gt;, it will call:</span></span>
<span class="line"><span>       set_perm file owner group filepermission context</span></span>
<span class="line"><span>    for all directories in &lt;directory&gt; (including itself), it will call:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h3 id="hot-install" tabindex="-1">Hot install <a class="header-anchor" href="#hot-install" aria-label="Permalink to &quot;Hot install {#hot-install}&quot;">​</a></h3><p>By default, a newly installed or updated module is staged in <code>/data/adb/modules_update</code> and only takes effect after a reboot. If your module does not depend on anything that only happens at boot, <code>customize.sh</code> can ask KernelSU to apply it right away:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># customize.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODULE_HOT_INSTALL_REQUEST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional: a script in your module to run once the new version is live</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODULE_HOT_RUN_SCRIPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hotinstall.sh</span></span></code></pre></div><p>The request is evaluated at install time, so the module decides whether a reboot is needed, for example by only requesting a hot install when the new version does not change its <code>system</code> files.</p><p>Once the installer (including <code>customize.sh</code> and a metamodule&#39;s <code>metainstall.sh</code>) finishes successfully, KernelSU:</p><ol><li>Replaces <code>/data/adb/modules/&lt;id&gt;</code> with the new version. The old directory is moved aside and only deleted on the next boot, so processes and mounts still using the old version keep working until then.</li><li>Loads the module&#39;s <code>sepolicy.rule</code>. Rules are only ever added, so rules dropped by the new version stay active until the next reboot.</li><li>Runs <code>MODULE_HOT_RUN_SCRIPT</code>, a path relative to the module directory, the same way as boot scripts: in the global mount namespace, with the script&#39;s directory as the working directory. Its output is shown in the installer, stdin is <code>/dev/null</code> and <code>SIGPIPE</code> is ignored, so background processes are not killed when the installer goes away. The installer waits up to 30 seconds for it; start long-running services in the background. If the script does not exist it is skipped.</li><li>Leaves no <code>update</code> flag behind, so the manager does not ask for a reboot.</li></ol><p>The module stays hot installed even if loading <code>sepolicy.rule</code> fails or the script fails or times out; check the installer output.</p><p>Like any install, this enables the module even if the previous version was disabled.</p><p>Effective immediately: the module files themselves, WebUI, <code>action.sh</code> and the information in <code>module.prop</code>.</p><p>Only applied on the next boot: files under <code>system</code> and the other partition directories (mounted by the metamodule), <code>system.prop</code>, <code>initrc</code>, <code>preinit</code>, and the <code>post-fs-data.sh</code>, <code>post-mount.sh</code>, <code>service.sh</code> and <code>boot-completed.sh</code> stages. They are <strong>not</strong> run during a hot install, but keep running on every boot as usual. If you need their effect now, do it in <code>MODULE_HOT_RUN_SCRIPT</code>, e.g. by starting your service or calling <code>resetprop</code>.</p><p>The old version is not stopped for you, and <code>uninstall.sh</code> is not run on updates. If your module runs a daemon, <code>MODULE_HOT_RUN_SCRIPT</code> should stop the old instance before starting the new one.</p><p>KernelSU falls back to applying the module on the next reboot, and prints the reason, when:</p><ul><li>The module being installed is a metamodule.</li><li>The device is in safe mode.</li><li><code>MODULE_HOT_RUN_SCRIPT</code> is not a relative path to a file inside the module (symlinks pointing outside the module are rejected).</li><li>The module directory cannot be replaced.</li></ul><h2 id="boot-scripts" tabindex="-1">Boot scripts <a class="header-anchor" href="#boot-scripts" aria-label="Permalink to &quot;Boot scripts&quot;">​</a></h2><p>In KernelSU, scripts are divided into two types based on their running mode: post-fs-data mode and late_start service mode.</p><ul><li>post-fs-data mode <ul><li>This stage is BLOCKING. The boot process is paused before execution is done or after 10 seconds.</li><li>Scripts run before any modules are mounted. This allows a module developer to dynamically adjust their modules before it gets mounted.</li><li>This stage happens before Zygote is started, which pretty much means everything in Android.</li><li><strong>WARNING:</strong> Using <code>setprop</code> will deadlock the boot process! Please use <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code> instead.</li><li><strong>Only run scripts in this mode if necessary</strong>.</li></ul></li><li>late_start service mode <ul><li>This stage is NON-BLOCKING. Your script runs in parallel with the rest of the booting process.</li><li><strong>This is the recommended stage to run most scripts</strong>.</li></ul></li></ul><p>In KernelSU, startup scripts are divided into two types based on their storage location: general scripts and module scripts.</p><ul><li>General scripts <ul><li>Placed in <code>/data/adb/post-fs-data.d</code>, <code>/data/adb/service.d</code>, <code>/data/adb/post-mount.d</code> or <code>/data/adb/boot-completed.d</code>.</li><li>Only executed if the script is set as executable (<code>chmod +x script.sh</code>).</li><li>Scripts in <code>post-fs-data.d</code> runs in post-fs-data mode, and scripts in <code>service.d</code> runs in late_start service mode.</li><li>Modules should <strong>NOT</strong> add general scripts during installation.</li></ul></li><li>Module scripts <ul><li>Placed in the module&#39;s own folder.</li><li>Only executed if the module is enabled.</li><li><code>post-fs-data.sh</code> runs in post-fs-data mode, <code>service.sh</code> runs in late_start service mode, <code>boot-completed.sh</code> runs on boot completed, <code>post-mount.sh</code> runs on OverlayFS mounted.</li></ul></li></ul><p>All boot scripts will run in KernelSU&#39;s BusyBox <code>ash</code> shell with Standalone Mode enabled.</p><h3 id="boot-scripts-process-explanation" tabindex="-1">Boot scripts process explanation <a class="header-anchor" href="#boot-scripts-process-explanation" aria-label="Permalink to &quot;Boot scripts process explanation&quot;">​</a></h3><p>The following is the relevant boot process for Android (some parts are omitted), which includes the operation of KernelSU (with leading asterisks), and can help you better understand the purpose of these module scripts:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0. Bootloader (nothing on screen)</span></span>
<span class="line"><span>load patched boot.img</span></span>
<span class="line"><span>load kernel:</span></span>
<span class="line"><span>    - GKI mode: GKI kernel with KernelSU integrated</span></span>
<span class="line"><span>    - LKM mode: stock kernel</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. kernel exec init (OEM logo on screen):</span></span>
<span class="line"><span>    - GKI mode: stock init</span></span>
<span class="line"><span>    - LKM mode: exec ksuinit, insmod kernelsu.ko, exec stock init</span></span>
<span class="line"><span>mount /dev, /dev/pts, /proc, /sys, etc.</span></span>
<span class="line"><span>  *preinit: before loading SELinux policy, the kernel runs modules&#39; preinit.conf</span></span>
<span class="line"><span>property-init -&gt; read default props</span></span>
<span class="line"><span>read init.rc</span></span>
<span class="line"><span>  *initrc injection: Kernel hook appends KernelSU core RC and module modules.rc to init.rc</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>early-init -&gt; init -&gt; late_init</span></span>
<span class="line"><span>early-fs</span></span>
<span class="line"><span>   start vold</span></span>
<span class="line"><span>fs</span></span>
<span class="line"><span>  mount /vendor, /system, /persist, etc.</span></span>
<span class="line"><span>post-fs-data</span></span>
<span class="line"><span>  *safe mode check</span></span>
<span class="line"><span>  *execute general scripts in post-fs-data.d/</span></span>
<span class="line"><span>  *load sepolicy.rule</span></span>
<span class="line"><span>  *execute metamodule&#39;s post-fs-data.sh (if exists)</span></span>
<span class="line"><span>  *execute module scripts post-fs-data.sh</span></span>
<span class="line"><span>    **(Zygisk)./bin/zygisk-ptrace64 monitor</span></span>
<span class="line"><span>  *(pre)load system.prop (same as resetprop -n)</span></span>
<span class="line"><span>  *execute metamodule&#39;s metamount.sh (mounts all modules)</span></span>
<span class="line"><span>  *execute general scripts in post-mount.d/</span></span>
<span class="line"><span>  *execute metamodule&#39;s post-mount.sh (if exists)</span></span>
<span class="line"><span>  *execute module scripts post-mount.sh</span></span>
<span class="line"><span>zygote-start</span></span>
<span class="line"><span>load_all_props_action</span></span>
<span class="line"><span>  *execute resetprop (actual set props for resetprop with -n option)</span></span>
<span class="line"><span>... -&gt; boot</span></span>
<span class="line"><span>  class_start core</span></span>
<span class="line"><span>    start-service logd, console, vold, etc.</span></span>
<span class="line"><span>  class_start main</span></span>
<span class="line"><span>    start-service adb, netd (iptables), zygote, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. kernel2user init (ROM animation on screen, start by service bootanim)</span></span>
<span class="line"><span>*execute general scripts in service.d/</span></span>
<span class="line"><span>*execute metamodule&#39;s service.sh (if exists)</span></span>
<span class="line"><span>*execute module scripts service.sh</span></span>
<span class="line"><span>*set props for resetprop without -p option</span></span>
<span class="line"><span>  **(Zygisk) hook zygote (start zygiskd)</span></span>
<span class="line"><span>  **(Zygisk) mount zygisksu/module.prop</span></span>
<span class="line"><span>start system apps (autostart)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>boot complete (broadcast ACTION_BOOT_COMPLETED event)</span></span>
<span class="line"><span>*execute general scripts in boot-completed.d/</span></span>
<span class="line"><span>*execute metamodule&#39;s boot-completed.sh (if exists)</span></span>
<span class="line"><span>*execute module scripts boot-completed.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. User operable (lock screen)</span></span>
<span class="line"><span>input password to decrypt /data/data</span></span>
<span class="line"><span>*actual set props for resetprop with -p option</span></span>
<span class="line"><span>start user apps (autostart)</span></span></code></pre></div><p>If you&#39;re interested in Android Init Language, it&#39;s recommended to read its <a href="https://android.googlesource.com/platform/system/core/+/master/init/README.md" target="_blank" rel="noreferrer">documentation</a>.</p><h2 id="late-load-mode" tabindex="-1">Late-load mode <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Late-load mode {#late-load-mode}&quot;">​</a></h2><p>In addition to the standard boot flow described above, KernelSU supports a <strong>late-load mode</strong> for LKM (Loadable Kernel Module) scenarios. In this mode, the KernelSU kernel module is loaded <strong>after the system has fully booted</strong>, rather than during the init process.</p><h3 id="when-does-late-load-happen" tabindex="-1">When does late-load happen? <a class="header-anchor" href="#when-does-late-load-happen" aria-label="Permalink to &quot;When does late-load happen?&quot;">​</a></h3><p>Late-load is triggered by running the <code>ksud late-load</code> command. This command:</p><ol><li>Detects the current KMI version and loads the corresponding <code>kernelsu.ko</code> from embedded assets.</li><li>Performs module initialization (SELinux rules, allowlist, features, etc.) that would normally happen during boot.</li></ol><p>Since the system is already fully running, certain boot-time mechanisms are unavailable or unnecessary.</p><h3 id="differences-from-standard-boot" tabindex="-1">Differences from standard boot <a class="header-anchor" href="#differences-from-standard-boot" aria-label="Permalink to &quot;Differences from standard boot&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Behavior</th><th style="text-align:center;">Standard boot</th><th style="text-align:center;">Late-load mode</th></tr></thead><tbody><tr><td>Kernel module loaded by init (PID 1)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">No (loaded after boot)</td></tr><tr><td>initrc injection (module <code>.rc</code> files to init.rc)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Unavailable</td></tr><tr><td>preinit (module <code>preinit/preinit.conf</code>)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Unavailable</td></tr><tr><td>kprobe hooks for ksud (execve/read/fstat/input)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Skipped</td></tr><tr><td>Safe mode detection (volume key)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Always disabled</td></tr><tr><td>Boot log capture (logcat/dmesg)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Skipped</td></tr><tr><td>Magisk coexistence check</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Skipped</td></tr><tr><td><code>post-fs-data</code> event reported to kernel</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Skipped</td></tr><tr><td><code>boot-completed</code> event reported to kernel</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Set directly during init</td></tr><tr><td><code>post-fs-data.sh</code> / <code>post-fs-data.d/</code> scripts</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Replaced by <code>late-load</code> stage</td></tr><tr><td><code>system.prop</code> loading</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>OverlayFS mount (metamodule)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td><code>post-mount.sh</code> / <code>post-mount.d/</code> scripts</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td><code>service.sh</code> / <code>service.d/</code> scripts</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td><code>boot-completed.sh</code> / <code>boot-completed.d/</code> scripts</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td><code>KSU_LATE_LOAD</code> environment variable</td><td style="text-align:center;">Not set</td><td style="text-align:center;">Set to <code>1</code></td></tr><tr><td>Kernel info flag <code>0x4</code></td><td style="text-align:center;">Not set</td><td style="text-align:center;">Set</td></tr></tbody></table><h3 id="script-execution-order" tabindex="-1">Script execution order <a class="header-anchor" href="#script-execution-order" aria-label="Permalink to &quot;Script execution order&quot;">​</a></h3><p>In late-load mode, the script execution order is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. Load kernelsu.ko (if not already loaded)</span></span>
<span class="line"><span>  2. Extract binaries, handle module updates, load SELinux rules, init features</span></span>
<span class="line"><span>  3. Execute late-load.d/ and module late-load scripts (blocking)</span></span>
<span class="line"><span>  4. Load system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. Execute metamodule mount script (OverlayFS)</span></span>
<span class="line"><span>  6. Execute post-mount.d/ and module post-mount.sh (blocking)</span></span>
<span class="line"><span>  7. Execute service.d/ and module service.sh (non-blocking)</span></span>
<span class="line"><span>  8. Execute boot-completed.d/ and module boot-completed.sh (non-blocking)</span></span></code></pre></div><h3 id="late-load-specific-scripts" tabindex="-1">Late-load specific scripts <a class="header-anchor" href="#late-load-specific-scripts" aria-label="Permalink to &quot;Late-load specific scripts&quot;">​</a></h3><p>Modules can provide a <code>late-load.sh</code> script that runs <strong>only</strong> in late-load mode, as a replacement for <code>post-fs-data.sh</code>. This script runs before OverlayFS mounting, similar to <code>post-fs-data.sh</code> in the standard flow.</p><p>Additionally, general scripts can be placed in <code>/data/adb/late-load.d/</code> to run during this stage.</p><h3 id="detecting-late-load-mode-in-scripts" tabindex="-1">Detecting late-load mode in scripts <a class="header-anchor" href="#detecting-late-load-mode-in-scripts" aria-label="Permalink to &quot;Detecting late-load mode in scripts&quot;">​</a></h3><p>Modules can detect late-load mode by checking the <code>KSU_LATE_LOAD</code> environment variable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Running in late-load mode</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>This allows modules to adjust their behavior accordingly, for example skipping operations that are only needed during early boot.</p>`,142)])])}const m=s(o,[["render",i]]);export{u as __pageData,m as default};
